start_node = 'b3e3e393c7'

def bfs_at_depth(adj, start, target_depth):
    """Find all nodes at exactly target_depth from start node"""
    if start not in adj:
        return []

    # BFS: (node, depth)
    queue = deque([(start, 0)])
    visited = {start}
    nodes_at_target_depth = []

    while queue:
        node, depth = queue.popleft()

        # If we've exceeded target depth, stop
        if depth > target_depth:
            break

        # If at target depth, add to results (but not the start node)
        if depth == target_depth and node != start:
            nodes_at_target_depth.append(node)

        # Continue BFS if we haven't reached target depth yet
        if depth < target_depth:
            for neighbor in adj.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, depth + 1))

    return nodes_at_target_depth

# Perform BFS at depth 8
result = bfs_at_depth(adj, start_node, 8)

print(f"Nodes at depth 8 from {start_node}:")
print(f"Count: {len(result)}")
print(f"Nodes: {sorted(result)}")

